import java.util.*;
import java.io.*;

public class Main {
    static final int MAX = 511;
    static int n, m, P;
    static int[][] dwu = new int[MAX][MAX];
    static long[] dp1 = new long[MAX];
    static long[][] dp2 = new long[MAX][MAX];
    static long[][] dp3 = new long[MAX][MAX];
    static long[] count = new long[MAX];

    static void multiply_self(int[] a, int b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (int)((long)a[i] * b % P);
        }
    }

    static int multiply(int a, int b) {
        return (int)((long)a * b % P);
    }

    static void add_mod(int[] a, int b) {
        a[0] += b;
        if (a[0] >= P) a[0] -= P;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        P = Integer.parseInt(st.nextToken());

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0) {
                    dwu[i][j] = 1;
                } else {
                    dwu[i][j] = dwu[i - 1][j];
                    add_mod(new int[]{dwu[i][j]}, dwu[i - 1][j - 1]);
                }
            }
        }

        dp1[0] = 0;
        count[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                int[] tempArr = new int[]{0};
                add_mod(tempArr, multiply(dp1[j], (int)count[i - j - 1]));
                add_mod(tempArr, multiply(dp1[i - j - 1], (int)count[j]));
                int temp = tempArr[0];
                temp = (int)((long)temp * (j + 1) % P);
                int addVal = (int)((long)count[i - j - 1] * count[j] % P);
                addVal = (int)((long)addVal * j * (j + 1) / 2 % P);
                temp = (temp + addVal) % P;
                temp = (int)((long)temp * dwu[i - 1][j] % P);
                add_mod(new int[]{dp1[i]}, temp);
                int temp2 = (int)((long)count[j] * count[i - j - 1] % P);
                temp2 = (int)((long)temp2 * (j + 1) % P);
                multiply_self(new int[]{temp2}, 1);
                count[i] = (count[i] + temp2) % P;
            }
            count[i] = (count[i] + count[i]) % P;
            dp1[i] = (dp1[i] + dp1[i]) % P;
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    if (j + k <= m && i + k + 1 <= n + 1) {
                        int temp = (int)dp2[i][j];
                        multiply_self(new int[]{temp}, dwu[m - j][k]);
                        multiply_self(new int[]{temp}, (int)count[k]);
                        int temp3 = (int)dp3[i][j];
                        multiply_self(new int[]{temp3}, (int)count[k]);
                        add_mod(new int[]{temp3}, multiply(dp1[k], (int)dp2[i][j]));
                        multiply_self(new int[]{temp3}, dwu[m - j][k]);
                        dp3[i + k + 1][j + k] = (dp3[i + k + 1][j + k] + temp3) % P;
                        dp2[i + k + 1][j + k] = (dp2[i + k + 1][j + k] + temp) % P;
                    }
                }
            }
        }

        System.out.println(dp3[n + 1][m]);
    }
}
